package com.gomgomapps.math.core;
import java.math.*;import java.util.*;import org.junit.Test;import static org.junit.Assert.*;
public class GradeSevenDecimalQuotientScopeTest {
 private static final String SYSTEM="na-nied-primary-2024-v1";
 private static Question q(String prompt){return new Question("decimalDivInt",prompt,"private expression","999");}
 @Test public void NormalNaSevenSuppliesOriginalDividendsTwoDigitDivisorsAndBothExactFormats(){
  var pack=GlobalCurriculum.packs("NA").stream().filter(p->p.id.equals(SYSTEM)).findFirst().orElseThrow();assertTrue(pack.inGrade("decimalDivInt",7));assertEquals(1,Catalog.ALL.stream().filter(s->s.id.equals("decimalDivInt")).count());CurriculumLimits limits=GlobalCurriculum.limits(SYSTEM,"decimalDivInt",7);assertTrue(DecimalWholeQuotients.selectedNaSeven("decimalDivInt",limits));assertFalse(DecimalWholeQuotients.selected("decimalDivInt",limits));assertEquals(99,limits.wholeMaximum(1));assertEquals(3,limits.decimalPlaces(1));assertEquals(99,limits.wholeDivisorMaximum());
  for(boolean mc:List.of(false,true)){Generator generator=new Generator(new Random(366));List<String> recent=new ArrayList<>();Set<Integer> places=new HashSet<>();Set<String> formats=new HashSet<>();boolean twoDigit=false;for(int i=0;i<300;i++){Question q=generator.next("decimalDivInt",recent,mc,limits);assertFalse(recent.contains(q.signature()));recent.add(q.signature());var publicValues=DecimalWholeQuotients.readGeneral(q);assertNotNull(publicValues);assertNotNull(DecimalWholeQuotients.read(q));assertTrue(publicValues.dividend().compareTo(new BigDecimal("100"))<0);assertTrue(publicValues.divisor().signum()>0&&publicValues.divisor().compareTo(BigInteger.valueOf(99))<=0);places.add(publicValues.dividend().scale());twoDigit|=publicValues.divisor().compareTo(BigInteger.TEN)>=0;formats.add(q.answerFormat);assertTrue(limits.allows(q));assertEquals(publicValues.finitePossible()?"decimalValue":"fraction",q.answerFormat);HelpPlan help=HelpPlan.forQuestion(q);assertEquals(publicValues.finitePossible()?7:9,help.size());assertFalse(help.canTransfer());String answer=q.answerFormat.equals("fraction")?publicValues.value().toString():publicValues.value().decimalText();assertTrue(new Checker().check(q,List.of(),List.of(answer)).correct());if(!q.choices.isEmpty())assertTrue(new Checker().check(q,List.of(),List.of(q.choices.get(q.correctChoice))).correct());}
   assertEquals(Set.of(1,2,3),places);assertEquals(Set.of("fraction","decimalValue"),formats);assertTrue(twoDigit);
  }Question ordinary=new Generator(new Random(3661)).create(Catalog.get("decimalDivInt"));assertNotNull(DecimalWholeQuotients.readGeneral(ordinary));assertNotNull(HelpPlan.forQuestion(ordinary));
 }
 @Test public void PublicSourceAndResultControlsAreExactAndIndependentOfPrivateMetadata(){
  CurriculumLimits selected=GlobalCurriculum.limits(SYSTEM,"decimalDivInt",7);for(String prompt:List.of("99.999 ÷ 99","0.000 ÷ 99","1.0 ÷ 3","99.9 ÷ 16")){Question q=q(prompt);q.expression=null;q.answers=null;assertTrue(selected.allows(q));assertNotNull(HelpPlan.forQuestion(q));assertNull(q.expression);assertNull(q.answers);}for(String prompt:List.of("100.00 ÷ 12","1.0001 ÷ 12","1.0 ÷ 100")){assertFalse(selected.allows(q(prompt)));assertTrue(CurriculumLimits.NONE.allows(q(prompt)));}
  assertTrue(new CurriculumLimits("decimalPlaces=4").allows(q("1.2345 ÷ 12")));assertFalse(new CurriculumLimits("decimalPlaces=3").allows(q("1.2345 ÷ 12")));assertTrue(new CurriculumLimits("wholeMaximum=1").allows(q("1.25 ÷ 99")));assertTrue(new CurriculumLimits("maxGiven=3;minGiven=0.9;maxResult=0.3;answerDecimalPlaces=1").allows(q("0.9 ÷ 3")));assertFalse(new CurriculumLimits("maxResult=0.299").allows(q("0.9 ÷ 3")));assertFalse(new CurriculumLimits("answerDecimalPlaces=3").allows(q("99.9 ÷ 16")));assertFalse(new CurriculumLimits("answerDecimalPlaces=6").allows(q("1.0 ÷ 3")));assertTrue(new CurriculumLimits("answerDomain=integer;integerSecondOperand=true").allows(q("4.0 ÷ 2")));assertFalse(new CurriculumLimits("answerDomain=integer").allows(q("1.0 ÷ 3")));assertFalse(new CurriculumLimits("maxSecondOperand=12").allows(q("1.0 ÷ 13")));assertTrue(new CurriculumLimits("wholeDigits=3;secondDigits=2").allows(q("123.4567 ÷ 12")));assertFalse(new CurriculumLimits("wholeDigits=2").allows(q("1.0 ÷ 123")));assertTrue(new CurriculumLimits("wholeDigits=2;secondDigits=3").allows(q("1.0 ÷ 123")));assertFalse(new CurriculumLimits("denominators=3").allows(q("1.0 ÷ 3")));assertFalse(new CurriculumLimits("wholeDivisorMaximum=99").allows(q("1.0 ÷ 3")));for(String invalid:List.of("wholeDivisorMaximum=0","wholeDivisorMaximum=100","wholeDecimalQuotients=unknown")){try{new CurriculumLimits(invalid);fail(invalid);}catch(IllegalArgumentException expected){}}
 }
 @Test public void LegacyNaSixSignaturesChoicesAndDeclaredSmallDivisorFreshnessArePreserved(){
  CurriculumLimits six=GlobalCurriculum.limits(SYSTEM,"decimalDivInt",6);assertTrue(DecimalWholeQuotients.selected("decimalDivInt",six));assertFalse(DecimalWholeQuotients.selectedNaSeven("decimalDivInt",six));assertFalse(DecimalWholeQuotients.selectedNaSeven("decimalDivInt",CurriculumLimits.NONE));Generator normal=new Generator(new Random(3662));Random direct=new Random(3662);for(int i=0;i<60;i++){Question expected=DecimalWholeQuotients.next(direct,six,Map.of()),actual=normal.next("decimalDivInt",List.of(),false,six);assertEquals(expected.signature(),actual.signature());assertEquals(expected.answerFormat,actual.answerFormat);assertEquals(DecimalWholeQuotients.guide(expected).frames.stream().map(f->f.expected).toList(),DecimalWholeQuotients.guide(actual).frames.stream().map(f->f.expected).toList());}
  for(int seed=3663;seed<3703;seed++){Random directChoices=new Random(seed);Question expected=DecimalWholeQuotients.next(directChoices,six,Map.of());Choices.build(expected,Catalog.get("decimalDivInt"),directChoices);Question actual=new Generator(new Random(seed)).next("decimalDivInt",List.of(),true,six);assertEquals(expected.signature(),actual.signature());assertEquals(expected.choices,actual.choices);assertEquals(expected.correctChoice,actual.correctChoice);if(!actual.choices.isEmpty())assertTrue(new Checker().check(actual,List.of(),List.of(actual.choices.get(actual.correctChoice))).correct());}CurriculumLimits tiny=new CurriculumLimits("wholeDecimalQuotients=true;wholeMaximum=1;decimalPlaces=1;wholeDivisorMaximum=1;maxGiven=1;nonnegative=true");List<String> recent=new ArrayList<>();Generator generator=new Generator(new Random(3664));for(int i=0;i<11;i++){Question q=generator.next("decimalDivInt",recent,false,tiny);assertFalse(recent.contains(q.signature()));recent.add(q.signature());assertEquals(BigInteger.ONE,DecimalWholeQuotients.readGeneral(q).divisor());}Question repeat=generator.next("decimalDivInt",recent,false,tiny);assertEquals(recent.get(0),repeat.signature());assertTrue(tiny.allows(repeat));assertEquals("1.0 ÷ 3",DecimalWholeQuotients.make("1.0",3).prompt);assertEquals("fraction",DecimalWholeQuotients.make("1.0",3).answerFormat);
 }
 @Test public void ExplicitFormatsAndOtherCurriculumProductsRemainUnchanged(){
  Question fraction=DecimalWholeQuotients.make("1.0",3),finite=DecimalWholeQuotients.make("99.9",16);assertEquals("fraction",fraction.answerFormat);assertTrue(FractionInput.available(fraction));assertTrue(FractionInput.defaultFraction(fraction));assertEquals("decimalValue",finite.answerFormat);assertFalse(FractionInput.available(finite));assertFalse(FractionInput.defaultFraction(finite));assertTrue(new Checker().check(finite,List.of(),List.of("6.24375")).correct());assertEquals("0",DecimalWholeQuotients.make("0.000",99).answers[0]);for(int divisor:List.of(0,-1,100)){try{DecimalWholeQuotients.make("1.0",divisor);fail("legacy divisor"+divisor);}catch(IllegalArgumentException expected){}}
  assertTrue(GlobalCurriculum.limits("ke-kicd-cbc-2024-v1","decimalDivInt",7).allows(q("1.2345 ÷ 12")));Question product=new Question("decimalMul","4.15 × 0.2","poison","999");assertTrue(new Checker().check(product,List.of(),List.of("0.83")).correct());assertEquals(9,HelpPlan.forQuestion(product).size());assertTrue(GlobalCurriculum.limits(SYSTEM,"decimalMul",7).includeWholeDecimalProducts());assertTrue(GlobalCurriculum.limits(SYSTEM,"decimalAdd",7).decimalDirectAnswers());Question other=new Question("decimalDiv","0.315 / 0.9","0.315 / 0.9","0.35");DecimalTeaching.attach(other);List<String> before=other.studyGuide.frames.stream().map(f->f.expected).toList();HelpPlan old=HelpPlan.forQuestion(other);assertEquals(7,old.size());assertEquals(before,other.studyGuide.frames.stream().map(f->f.expected).toList());assertEquals("decimal-arithmetic-relations-v1",other.studyGuide.teachingVersion);assertFalse(old.canTransfer());
 }
}
